package com.bank.tgwiso;

import java.util.logging.*;

public class IsolationDemo {
    private static final Logger log = Logger.getLogger("TGWIso");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        TransitGateway tgw = new TransitGateway();
        tgw.createRouteTable("PROD");
        tgw.createRouteTable("NONPROD");

        // Associate attachments with their route table.
        tgw.associate("prod-pca",    "PROD");
        tgw.associate("prod-nonpca", "PROD");
        tgw.associate("dev",         "NONPROD");

        // Propagate routes: production routes only into PROD table.
        tgw.propagate("prod-pca",    "PROD");
        tgw.propagate("prod-nonpca", "PROD");
        tgw.propagate("dev",         "NONPROD");

        log.info(() -> "prod-pca → prod-nonpca: " + tgw.canReach("prod-pca", "prod-nonpca"));
        log.warning(() -> "dev → prod-pca:        " + tgw.canReach("dev", "prod-pca"));
        log.warning(() -> "prod-pca → dev:        " + tgw.canReach("prod-pca", "dev"));
    }
}

// ─── Would be in TgwRouteTable.java ───
class TgwRouteTable {
    final String name;
    final java.util.Set<String> propagatedAttachments = new java.util.HashSet<>();
    TgwRouteTable(String name) { this.name = name; }
}

// ─── Would be in TransitGateway.java ───
class TransitGateway {
    private final java.util.Map<String, TgwRouteTable> tables = new java.util.HashMap<>();
    private final java.util.Map<String, String> association = new java.util.HashMap<>(); // attach → table

    void createRouteTable(String name) { tables.put(name, new TgwRouteTable(name)); }
    void associate(String attachment, String tableName) { association.put(attachment, tableName); }
    void propagate(String attachment, String tableName) {
        tables.get(tableName).propagatedAttachments.add(attachment); // route becomes visible there
    }
    // Reachable only if the SENDER's associated table has a route to the destination.
    String canReach(String from, String to) {
        String fromTable = association.get(from);
        boolean hasRoute = fromTable != null
                && tables.get(fromTable).propagatedAttachments.contains(to);
        return hasRoute ? "ALLOWED (route exists in " + fromTable + ")"
                        : "DENIED (no route in " + fromTable + " — isolated)";
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
